/**
 * Simulated learners reading stories generated by the mock model. Checks that the
 * learner model keeps skills apart (a reader who speaks little, a heritage speaker who
 * cannot read), that difficulty follows vocabulary, and that placement on corpus
 * frequency ranks works end to end. Everything is seeded and deterministic.
 */
import { describe, expect, it } from 'vitest';
import { createMockModel, mockTokenize } from '../model/mock';
import { MOCK_CORPUS_ES } from '../model/mockCorpus';
import { cliffRungFor, deriveParams, estimateVocabulary, showText } from './difficulty';
import { LearnerModel } from './model';
import { PlacementTracker } from './placement';
import { lexemeKey, type LearnerEvent, type Skill } from './types';

const DAY = 86_400_000;
const T0 = Date.UTC(2026, 10, 15, 8, 0, 0);

/** Words of a text: merge sub-word pieces, keep letter words, lowercase (test stand-in for a pack). */
function words(text: string): string[] {
  const out: string[] = [];
  let cur = '';
  for (const p of mockTokenize(text)) {
    if (!p.isWord) {
      if (cur) out.push(cur);
      cur = '';
      continue;
    }
    if (p.startsUnit) {
      if (cur) out.push(cur);
      cur = p.text.trim();
    } else {
      cur += p.text;
    }
  }
  if (cur) out.push(cur);
  return out.map((w) => w.toLowerCase());
}

/** Frequency ranks of the corpus words (1 = most frequent; ties alphabetical). */
function corpusRanks(): Map<string, number> {
  const counts = new Map<string, number>();
  for (const s of MOCK_CORPUS_ES) for (const w of words(s)) counts.set(w, (counts.get(w) ?? 0) + 1);
  const sorted = [...counts.entries()].sort((a, b) => b[1] - a[1] || (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0));
  return new Map(sorted.map(([w], i) => [w, i + 1]));
}

const RANKS = corpusRanks();
const KEYS = [...RANKS.keys()].map((w) => lexemeKey('es', w));
const rankOf = (key: string) => RANKS.get(key.slice(3));

/** A synthetic learner: per skill, the frequency rank up to which they know words. */
type Profile = Record<Skill, number>;

const PROFILES: Record<string, Profile> = {
  brandNew: { meaning: 0, sound: 0, written: 0, speaking: 0 },
  early: { meaning: 15, sound: 10, written: 15, speaking: 5 },
  readerWeakSpeaking: { meaning: 120, sound: 15, written: 120, speaking: 3 },
  heritage: { meaning: 120, sound: 120, written: 3, speaking: 100 },
  advanced: { meaning: 1000, sound: 1000, written: 1000, speaking: 1000 },
};

/** Stories from the mock model, deterministic per day. */
async function storyForDay(day: number): Promise<string[]> {
  const model = createMockModel();
  const prompts = ['Marta', 'Ayer', 'Estoy', 'Vamos'];
  const out: string[] = [];
  for (const [i, prompt] of prompts.entries()) {
    const texts = await model.generate(prompt, { n: 3, maxTokens: 14, temperature: 0.9, seed: day * 100 + i * 10 });
    for (const t of texts) out.push(`${prompt} ${t}`);
  }
  return out;
}

/** What the profile does with each word of a sentence, as learner events. */
function eventsFor(learner: LearnerModel, profile: Profile, sentence: string, at: number): LearnerEvent[] {
  const ws = words(sentence);
  const events: LearnerEvent[] = [];
  const params = deriveParams({ vocab: estimateVocabulary(learner, at, KEYS) });
  ws.forEach((w, i) => {
    const key = lexemeKey('es', w);
    const rank = RANKS.get(w) ?? 10_000;
    const t = at + i * 2000;
    const knows = (s: Skill) => rank <= profile[s];
    // Every word is spoken; text is shown on top of the audio until the word is known by ear.
    events.push(knows('sound') ? { type: 'heard', key, at: t } : { type: 'tap_rehear', key, at: t });
    if (showText(learner, key, t, params)) {
      if (knows('written')) events.push({ type: 'read', key, at: t });
    } else if (!knows('sound')) {
      events.push({ type: 'hold_reveal', key, at: t });
    }
    if (!knows('meaning') && !knows('sound')) events.push({ type: 'gloss_lookup', key, at: t });
  });
  // A cliff on every third word.
  ws.forEach((w, i) => {
    if (i % 3 !== 2) return;
    const key = lexemeKey('es', w);
    const rank = RANKS.get(w) ?? 10_000;
    const t = at + i * 2000 + 1000;
    const rung = cliffRungFor(learner, key, t);
    // Options are a recognition task; hint and free need production.
    const ok = rung === 'options' ? rank <= Math.max(profile.meaning, profile.sound) : rank <= profile.speaking;
    events.push({ type: 'cliff_answer', key, at: t, credit: ok ? 'full' : 'none', rung });
  });
  return events;
}

async function simulate(profile: Profile, days: number, prior?: (key: string, skill: Skill) => number): Promise<LearnerModel> {
  const learner = new LearnerModel({ prior });
  for (let d = 0; d < days; d++) {
    const sentences = await storyForDay(d);
    sentences.forEach((s, i) => {
      for (const e of eventsFor(learner, profile, s, T0 + d * DAY + i * 60_000)) learner.apply(e);
    });
  }
  return learner;
}

function meanP(learner: LearnerModel, keys: string[], skill: Skill, now: number): number {
  return keys.reduce((s, k) => s + learner.pKnown(k, skill, now), 0) / Math.max(1, keys.length);
}

describe('simulated learners on mock-model stories', () => {
  const days = 6;
  const now = T0 + (days - 1) * DAY + 3_600_000;
  const common = KEYS.filter((k) => (rankOf(k) ?? 1e9) <= 10);
  /** Words the reader knows by sight but not by ear, and the heritage speaker knows by ear. */
  const mid = KEYS.filter((k) => (rankOf(k) ?? 1e9) > 15 && (rankOf(k) ?? 1e9) <= 100);

  it('the mock produces stories with words from the corpus', async () => {
    const s = await storyForDay(0);
    expect(s.length).toBe(12);
    const ws = s.flatMap(words);
    expect(ws.length).toBeGreaterThan(50);
    expect(ws.filter((w) => RANKS.has(w)).length).toBe(ws.length);
  });

  it('keeps meaning and speaking apart for a reader who speaks little', async () => {
    const reader = await simulate(PROFILES.readerWeakSpeaking as Profile, days);
    expect(meanP(reader, common, 'meaning', now)).toBeGreaterThan(meanP(reader, common, 'speaking', now) + 0.2);
    expect(meanP(reader, common, 'written', now)).toBeGreaterThan(meanP(reader, common, 'speaking', now));
  });

  it('a heritage speaker hears and speaks well but reads poorly, and gets tiles and free cliffs', async () => {
    const heritage = await simulate(PROFILES.heritage as Profile, days);
    const reader = await simulate(PROFILES.readerWeakSpeaking as Profile, days);
    expect(meanP(heritage, mid, 'sound', now)).toBeGreaterThan(meanP(reader, mid, 'sound', now) + 0.1);
    expect(meanP(heritage, common, 'speaking', now)).toBeGreaterThan(meanP(reader, common, 'speaking', now) + 0.2);
    expect(meanP(heritage, common, 'written', now)).toBeLessThan(meanP(reader, common, 'written', now));
    const params = deriveParams({ vocab: estimateVocabulary(heritage, now, KEYS) });
    const all = [...common, ...mid];
    const tiles = all.filter((k) => !showText(heritage, k, now, params)).length;
    const readerTiles = all.filter((k) => !showText(reader, k, now, params)).length;
    expect(tiles).toBeGreaterThan(readerTiles);
    const freeRungs = common.filter((k) => cliffRungFor(heritage, k, now) !== 'options').length;
    const readerFree = common.filter((k) => cliffRungFor(reader, k, now) !== 'options').length;
    expect(freeRungs).toBeGreaterThanOrEqual(readerFree);
  });

  it('vocabulary and difficulty grow with the learner', async () => {
    const vocab: number[] = [];
    for (const name of ['brandNew', 'early', 'advanced']) {
      const learner = await simulate(PROFILES[name] as Profile, 3);
      vocab.push(estimateVocabulary(learner, T0 + 3 * DAY, KEYS));
    }
    expect(vocab[1]).toBeGreaterThan(vocab[0] ?? Infinity);
    expect(vocab[2]).toBeGreaterThan(vocab[1] ?? Infinity);
    const [lo, mid, hi] = vocab.map((v) => deriveParams({ vocab: v }));
    expect(mid?.sentenceWords.max).toBeGreaterThanOrEqual(lo?.sentenceWords.max ?? Infinity);
    expect(hi?.sentenceWords.max).toBeGreaterThan(lo?.sentenceWords.max ?? Infinity);
  });

  it('a brand-new learner always has a next step: options cliffs, text shown, new words allowed', async () => {
    const prior = PlacementTracker.brandNew(['es:mercado', 'es:fruta']);
    const learner = await simulate(PROFILES.brandNew as Profile, 1, prior);
    const t = T0 + DAY;
    const params = deriveParams({ vocab: estimateVocabulary(learner, t, KEYS) });
    expect(params.newWordsPerSentence).toBeGreaterThan(0);
    for (const k of KEYS.slice(0, 20)) {
      expect(cliffRungFor(learner, k, t)).toBe('options');
      expect(showText(learner, k, t, params)).toBe(true);
    }
    expect(learner.pKnown('es:mercado', 'meaning', T0)).toBeGreaterThan(learner.pKnown('es:casa', 'meaning', T0));
  });

  it('placement on corpus frequency ranks finds a learner who knows the 30 commonest words', () => {
    const T = 30;
    const byRank = [...RANKS.entries()].sort((a, b) => a[1] - b[1]);
    const tracker = new PlacementTracker({ startRank: 4 });
    let i = 0;
    while (!tracker.done && i < 100) {
      const band = tracker.nextBand();
      const inBand = byRank.filter(([, r]) => r >= band.minRank && r < band.maxRank);
      const pick = inBand[i % Math.max(1, inBand.length)] ?? byRank[byRank.length - 1];
      if (!pick) break;
      tracker.record(lexemeKey('es', pick[0]), pick[1], pick[1] <= T);
      i++;
    }
    const est = tracker.estimate().thresholdRank;
    expect(est).toBeGreaterThan(T / 2);
    expect(est).toBeLessThan(T * 2);
    const learner = new LearnerModel({ prior: tracker.prior(rankOf) });
    const commonest = byRank[0]?.[0] ?? '';
    const rarest = byRank[byRank.length - 1]?.[0] ?? '';
    expect(learner.pKnown(lexemeKey('es', commonest), 'meaning', T0)).toBeGreaterThan(0.8);
    expect(learner.pKnown(lexemeKey('es', rarest), 'meaning', T0)).toBeLessThan(0.2);
  });
});
